import{_ as i,a as o,b as d,c as n,d as l,e as c,f as h,g,h as p,i as u,j as m,k as f,l as b,m as v,n as w,o as _,p as k,q as e,r as y,s as L,t as r,u as S,v as x,w as C,x as A,y as P,z as T,A as K,B as I,C as E,D,E as j}from"./chunks/cloudflare.KvEfh_SJ.js";import{_ as O}from"./chunks/pikube-technical-stacks.drawio.YJ_Qv9fO.js";import{_ as N,c as M,o as R,j as a,a0 as V,a as B,t as H}from"./chunks/framework.2ZoCBPOS.js";const q="/pikube-kubernetes-service/assets/volcano.C8CBW08P.svg",Z=JSON.parse('{"title":"PiKube: A Deep Dive into a Modern, Automated Kubernetes Platform","description":"This project establishes PiKube, a home-based Kubernetes cluster on ARM bare metal, emphasizing full automation, a comprehensive observability stack, and advanced workload management for microservices, real-time data, and high-performance batch processing.","frontmatter":{"title":"PiKube: A Deep Dive into a Modern, Automated Kubernetes Platform","permalink":"/docs/1-project-architecture-purpose/1-project-purpose-v1","description":"This project establishes PiKube, a home-based Kubernetes cluster on ARM bare metal, emphasizing full automation, a comprehensive observability stack, and advanced workload management for microservices, real-time data, and high-performance batch processing.","last_modified_at":"2025-07-09"},"headers":[],"relativePath":"1-project-architecture-purpose/1-project-purpose.md","filePath":"1-project-architecture-purpose/1-project-purpose.md"}'),F={name:"1-project-architecture-purpose/1-project-purpose.md"},G={id:"frontmatter-title",tabindex:"-1"};function z(s,t,U,$,W,Y){return R(),M("div",null,[a("h1",G,[B(H(s.$frontmatter.title)+" ",1),t[0]||(t[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),t[1]||(t[1]=V('<p align="center"><img alt="pikube-logo" src="'+i+'" width="80%"></p><h2 id="project-scope-pikube-kubernetes-service" tabindex="-1">Project Scope: PiKube Kubernetes Service <a class="header-anchor" href="#project-scope-pikube-kubernetes-service" aria-label="Permalink to &quot;Project Scope: PiKube Kubernetes Service&quot;">​</a></h2><p>The primary goal of this project is to build a sophisticated, home-based Kubernetes cluster on ARM bare metal nodes (Raspberry Pis and Orange Pis). This is not just a simple cluster; it is a fully automated, observable, and extensible platform designed to explore the frontiers of modern cloud-native technologies.</p><p>The project is built on two core pillars:</p><ol><li><p><strong>Extreme Automation:</strong> Leveraging Infrastructure as Code (IaC) and GitOps principles with <strong>Ansible</strong>, <strong>cloud-init</strong>, and <strong>Argo CD</strong>, the entire cluster lifecycle—from bare-metal provisioning to application deployment—is automated. This ensures consistency, repeatability, and rapid recovery.</p></li><li><p><strong>Deep Observability:</strong> A comprehensive, integrated observability stack provides deep insights into the cluster&#39;s health and performance. This includes:</p><ul><li><strong>Metrics:</strong> <strong>Prometheus</strong> for time-series monitoring and alerting.</li><li><strong>Logs:</strong> A dual-stack approach with <strong>Loki</strong> for efficient, real-time log aggregation and the <strong>EFK stack (Elasticsearch, Fluentd/Fluentbit, Kibana)</strong> for powerful, in-depth log analytics.</li><li><strong>Traces:</strong> <strong>Grafana Tempo</strong> for distributed tracing to understand the flow of requests across microservices.</li><li><strong>Visualization:</strong> <strong>Grafana</strong> as a single pane of glass for all metrics, logs, and traces.</li></ul></li></ol><p>Beyond the foundational platform, PiKube is designed to run a diverse set of modern workloads, making it an ideal environment for learning and experimentation:</p><ul><li><strong>Microservices Architecture:</strong> With <strong>Linkerd</strong> service mesh, <strong>Keycloak</strong> for API security (OAuth 2.0/OIDC), and <strong>HashiCorp Vault</strong> for secrets management, the cluster is primed for secure, reliable, and observable microservices.</li><li><strong>Real-Time Data Streaming:</strong> <strong>Apache Kafka</strong>, managed by the <strong>Strimzi</strong> operator, provides a robust backbone for real-time data pipelines and event-driven architectures.</li><li><strong>High-Performance Batch Computing:</strong> <strong>Volcano</strong>, a CNCF batch scheduling system, is integrated to efficiently manage and schedule high-performance computing (HPC), machine learning, and big data workloads, which are not well-served by the default Kubernetes scheduler.</li><li><strong>Persistent Storage:</strong> <strong>Longhorn</strong> provides resilient, distributed block storage for stateful applications, while <strong>Minio</strong> offers an S3-compatible object store.</li><li><strong>Backup and Recovery:</strong> <strong>Velero</strong> and <strong>Restic</strong> ensure that the cluster&#39;s state and application data are backed up and can be restored.</li></ul><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ul><li><strong>Heterogeneous ARM Bare Metal:</strong> A mix of Raspberry Pi and Orange Pi nodes to explore the challenges and opportunities of a diverse hardware environment.</li><li><strong>Lightweight &amp; Efficient:</strong> <strong>K3s</strong> as the Kubernetes distribution of choice, optimized for resource-constrained environments.</li><li><strong>Open Source &amp; CNCF-Aligned:</strong> A strong commitment to using open-source technologies, with a preference for projects within the Cloud Native Computing Foundation (CNCF) ecosystem.</li><li><strong>Cutting-Edge Exploration:</strong> Use of the latest stable versions of all tools to stay at the forefront of the cloud-native landscape.</li><li><strong>Declarative &amp; Git-Driven:</strong> All aspects of the cluster and its applications are defined declaratively in a Git repository, which serves as the single source of truth.</li></ul><h2 id="open-source-technologies-building-the-cluster" tabindex="-1">Open Source Technologies: Building the Cluster <a class="header-anchor" href="#open-source-technologies-building-the-cluster" aria-label="Permalink to &quot;Open Source Technologies: Building the Cluster&quot;">​</a></h2><p>The diagram below provides a comprehensive overview of the technology stack that powers the PiKube platform.</p><p align="center"><img alt="pikube-technical-stacks" src="'+O+'" width="100%"></p><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th></th><th></th><th>Technology Stack</th><th>Description</th></tr></thead><tbody><tr><td rowspan="8" class="vertical-cell"><div class="vertical-text">OBSERVABILITY</div></td><td><img width="32" src="'+o+'" alt="Grafana Logo"></td><td><a href="https://grafana.com/oss/grafana/">Grafana</a></td><td>Unified visualization for metrics, logs, and traces.</td></tr><tr><td><img width="32" src="'+d+'" alt="Kibana Logo"></td><td><a href="https://www.elastic.co/kibana/">Kibana</a></td><td>Advanced log analytics and visualization.</td></tr><tr><td><img width="32" src="'+n+'" alt="Elasticsearch Logo"></td><td><a href="https://www.elastic.co/elasticsearch/">Elasticsearch</a></td><td>Full-text search and analytics engine for logs.</td></tr><tr><td><img width="32" src="'+l+'" alt="Tempo Logo"></td><td><a href="https://grafana.com/oss/tempo/">Tempo</a></td><td>High-scale distributed tracing backend.</td></tr><tr><td><img width="32" src="'+c+'" alt="Prometheus Logo"></td><td><a href="https://prometheus.io/">Prometheus</a></td><td>Metrics-based monitoring and alerting.</td></tr><tr><td><img width="32" src="'+h+'" alt="Fluentd Logo"></td><td><a href="https://www.fluentd.org/">Fluentd</a></td><td>Log aggregation and forwarding.</td></tr><tr><td><img width="60" src="'+g+'" alt="Fluentbit Logo"></td><td><a href="https://fluentbit.io/">Fluentbit</a></td><td>Lightweight log collection.</td></tr><tr><td><img width="32" src="'+p+'" alt="Loki Logo"></td><td><a href="https://grafana.com/oss/loki/">Loki</a></td><td>Horizontally-scalable, multi-tenant log aggregation.</td></tr><tr><td rowspan="3" class="vertical-cell"><div class="vertical-text">AUTOMATION</div></td><td><img width="32" src="'+u+'" alt="Ansible Logo"></td><td><a href="https://www.ansible.com">Ansible</a></td><td>Automates system configuration and external service integration.</td></tr><tr><td><img width="32" src="'+m+'" alt="ArgoCD Logo"></td><td><a href="https://argoproj.github.io/cd">ArgoCD</a></td><td>Declarative, GitOps-based continuous delivery.</td></tr><tr><td><img width="32" src="'+f+'" alt="Cloud-init Logo"></td><td><a href="https://cloudinit.readthedocs.io/en/latest/">Cloud-init</a></td><td>Automates initial OS configuration.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">AUTHENTICATION</div></td><td><img width="32" src="'+b+'" alt="Keycloak Logo"></td><td><a href="https://www.keycloak.org/">Keycloak</a></td><td>OpenID Connect &amp; OAuth 2.0 Identity and Access Management.</td></tr><tr><td><img width="32" src="'+v+'" alt="OAuth2.0 Proxy Logo"></td><td><a href="https://oauth2-proxy.github.io/oauth2-proxy/">OAuth2-Proxy</a></td><td>Reverse proxy for adding authentication to applications.</td></tr><tr><td rowspan="3" class="vertical-cell"><div class="vertical-text">ORCHESTRATION</div></td><td><img width="32" src="'+w+'" alt="K3S Logo"></td><td><a href="https://k3s.io/">K3S</a></td><td>Lightweight, certified Kubernetes distribution.</td></tr><tr><td><img width="32" src="'+_+'" alt="containerd Logo"></td><td><a href="https://containerd.io/">containerd</a></td><td>Industry-standard container runtime.</td></tr><tr><td><img width="32" src="'+q+'" alt="Volcano Logo"></td><td><a href="https://volcano.sh/">Volcano</a></td><td>Batch scheduling for HPC and AI/ML workloads.</td></tr><tr><td rowspan="3" class="vertical-cell"><div class="vertical-text">SECURITY</div></td><td><img width="32" src="'+k+'" alt="Cert-manager Logo"></td><td><a href="https://cert-manager.io">Cert-manager</a></td><td>Automated TLS certificate management.</td></tr><tr><td><img width="32" src="'+e+'" alt="Vault Logo"></td><td><a href="https://www.vaultproject.io/">Hashicorp Vault</a></td><td>Centralized secrets management.</td></tr><tr><td><img width="32" src="'+y+'" alt="External Secrets Logo"></td><td><a href="https://external-secrets.io/">External Secrets Operator</a></td><td>Syncs secrets from external APIs into Kubernetes.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">STORAGE</div></td><td><img width="32" src="'+L+'" alt="Longhorn Logo"></td><td><a href="https://longhorn.io/">Longhorn</a></td><td>Cloud-native distributed block storage.</td></tr><tr><td><img width="60" src="'+r+'" alt="Minio Logo"></td><td><a href="https://min.io/">Minio</a></td><td>High-performance, S3-compatible object storage.</td></tr><tr><td rowspan="7" class="vertical-cell"><div class="vertical-text">NETWORK</div></td><td><img width="32" src="'+S+'" alt="CoreDNS Logo"></td><td><a href="https://coredns.io/">CoreDNS</a></td><td>Cluster DNS resolution.</td></tr><tr><td><img width="32" src="'+x+'" alt="Flannel Logo"></td><td><a href="https://github.com/flannel-io/flannel">Flannel</a></td><td>CNI plugin for pod-to-pod networking.</td></tr><tr><td><img width="32" src="'+C+'" alt="HA Proxy Logo"></td><td><a href="https://www.haproxy.org/">HA Proxy</a></td><td>High-availability load balancer for the Kubernetes API.</td></tr><tr><td><img width="32" src="'+A+'" alt="Metal LB Logo"></td><td><a href="https://metallb.universe.tf/">Metal LB</a></td><td>Bare-metal load balancer for Kubernetes services.</td></tr><tr><td><img width="32" src="'+P+'" alt="Ingress NGINX Logo"></td><td><a href="https://kubernetes.github.io/ingress-nginx/">Ingress NGINX</a></td><td>Manages external access to cluster services.</td></tr><tr><td><img width="32" src="'+T+'" alt="Traefik Logo"></td><td><a href="https://traefik.io/">Traefik</a></td><td>Cloud-native Ingress Controller.</td></tr><tr><td><img width="32" src="'+K+'" alt="Linkerd Logo"></td><td><a href="https://linkerd.io/">Linkerd</a></td><td>Ultralight, security-first service mesh.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">BACKUP</div></td><td><img width="32" src="'+I+'" alt="Velero Logo"></td><td><a href="https://velero.io/">Velero</a></td><td>Cluster backup and restore.</td></tr><tr><td><img width="32" src="'+E+'" alt="Restic Logo"></td><td><a href="https://restic.net/">Restic</a></td><td>Secure and efficient file-level backup.</td></tr></tbody></table></div><h2 id="external-services-and-dependencies" tabindex="-1">External Services and Dependencies <a class="header-anchor" href="#external-services-and-dependencies" aria-label="Permalink to &quot;External Services and Dependencies&quot;">​</a></h2><p>While PiKube is designed to be as self-contained as possible, it leverages a few external services for public-facing endpoints.</p><h3 id="cloud-based-services" tabindex="-1">Cloud-Based Services <a class="header-anchor" href="#cloud-based-services" aria-label="Permalink to &quot;Cloud-Based Services&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The use of these external services is optional. The cluster can operate in a fully private mode, but will lack publicly trusted TLS certificates for its services.</p></div><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th></th><th></th><th>Service Provider</th><th>Role</th><th>Strategic Importance</th></tr></thead><tbody><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">SECURITY</div></td><td><img width="200" src="'+D+'" alt="Let&#39;s Encrypt Logo"></td><td><a href="https://letsencrypt.org/">Let&#39;s Encrypt</a></td><td>TLS Certificate Authority</td><td>Provides free, trusted TLS certificates for securing public-facing services.</td></tr><tr><td><img width="150" src="'+j+'" alt="Cloudflare Logo"></td><td><a href="https://www.cloudflare.com/">Cloudflare</a></td><td>DNS &amp; Web Security</td><td>Manages the public DNS records for the cluster and provides an API for automated DNS-01 challenges with Cert-Manager.</td></tr></tbody></table></div><h3 id="externally-hosted-services" tabindex="-1">Externally Hosted Services <a class="header-anchor" href="#externally-hosted-services" aria-label="Permalink to &quot;Externally Hosted Services&quot;">​</a></h3><p>Certain critical services are hosted outside the main Kubernetes cluster to avoid circular dependencies and ensure the cluster can be bootstrapped from a clean state.</p><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th></th><th></th><th>Technology Stack</th><th>Strategic Importance</th></tr></thead><tbody><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">STRATEGIC SERVICES</div></td><td><img width="60" src="'+r+'" alt="Minio Logo"></td><td><a href="https://min.io/">Minio</a></td><td>S3 Object Store for cluster backups.</td></tr><tr><td><img width="32" src="'+e+'" alt="Vault Logo"></td><td><a href="https://www.vaultproject.io/">Hashicorp Vault</a></td><td>Centralized secrets management.</td></tr></tbody></table></div><ul><li><p><strong>Minio:</strong> Provides an S3-compatible object store for <strong>Velero</strong> backups. It is hosted on a dedicated node to ensure that cluster backups are independent of the cluster&#39;s own storage systems.</p></li><li><p><strong>Hashicorp Vault:</strong> Manages all sensitive secrets for the cluster. It is hosted on the gateway node and is a prerequisite for many other services, making it essential to be available before the rest of the cluster comes online.</p></li></ul>',22))])}const tt=N(F,[["render",z]]);export{Z as __pageData,tt as default};
